-- The verb notes in plain English, every Arabic term beside its English and no line opening in Arabic (owner, 2026-10-16:
-- "Intransitive: its مجهول …" read as jargon in a jumble).
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'The Qurʾān does not use this verb. The noun إِلَٰه is on the pattern فِعَال with a passive sense: the one who is worshipped (مَأْلُوه).') WHERE id = 'PAR:اله:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'It takes no direct object, so its passive is made through its preposition: تِيبَ عَلَيْهِ, “he was turned to in mercy”.') WHERE id = 'PAR:توب:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'It describes a state, so it has no passive. Its describing word is the adjective شَدِيد, “severe, strong”.') WHERE id = 'PAR:شدد:I:daraba';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'The same letters on another pattern make another verb: شَدَّ يَشِدُّ, “to be strong”, and شَدَّهُ يَشُدُّهُ, “to bind it fast”.') WHERE id = 'PAR:شدد:I:nasara';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'It has two verbal nouns with two meanings: طُول is length, and طَوْل is bounty that reaches far — the word in ذِي الطَّوْلِ (40:3).') WHERE id = 'PAR:طول:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'It takes no object and describes a state, so it has no passive. Its describing word is the adjective عَزِيز, “mighty”, used 101 times in the Qurʾān.') WHERE id = 'PAR:عزز:I:daraba';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'The same letters on another pattern give another meaning: عَزَّ يَعِزُّ, “to be mighty”, and عَزَّهُ يَعُزُّهُ, “to overpower him”.') WHERE id = 'PAR:عزز:I:nasara';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'Its tool-noun مِغْفَر is the helmet that covers the head — the picture behind the root: to cover. مَغْفِرَة is a verbal noun with مـ (مَصْدَر مِيمِيّ).') WHERE id = 'PAR:غفر:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'The one who accepts is قَابِل. God is «قَابِلِ ٱلتَّوْبِ» (40:3): He accepts repentance.') WHERE id = 'PAR:قبل:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'A hollow verb: the و shows in يَقُولُ and drops in قُلْ and قُلْتُ. Its verbal nouns are from al-Ṣiḥāḥ and al-Miṣbāḥ; the Lisān adds قِيلًا, which al-Miṣbāḥ counts as a plain noun.') WHERE id = 'PAR:قول:I';
UPDATE ar_ling_root_form_paradigm SET paradigm_json = json_set(paradigm_json, '$.note', 'It behaves like a sound verb: the doubled و stays. Al-Zamakhsharī on 69:44 says the form carries effort: «كأن فيه تكلفا». It takes a direct object (52:33) or عَلَى with an object (69:44).') WHERE id = 'PAR:قول:V';
UPDATE kmaps_cache_version SET version = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family IN ('rest','books');
